function solve(input) {
  const balances={...input.balances};
  const versions=Object.fromEntries(Object.keys(balances).map(k=>[k,0]));
  const acceptedIds=new Set();
  const receipts=input.events.map(e=>{
    if(acceptedIds.has(e.id))return {id:e.id,status:'duplicate'};
    for (const account of Object.keys(e.expected || {})) {
      if (e.expected[account] !== versions[account]) {
        return {id:e.id,status:'rejected'};
      }
    }

    // Keep only touched accounts in the draft. Failed moves never change state.
    const draft = new Map();
    const moves = e.moves === undefined ? [e] : e.moves;
    for (const move of moves) {
      const fromBalance = draft.has(move.from) ? draft.get(move.from) : balances[move.from];
      if (fromBalance < move.amount) return {id:e.id,status:'rejected'};
      const toBalance = draft.has(move.to) ? draft.get(move.to) : balances[move.to];
      draft.set(move.from, fromBalance - move.amount);
      draft.set(move.to, toBalance + move.amount);
    }
    for (const [account, balance] of draft) {
      balances[account] = balance;
      versions[account]++;
    }
    acceptedIds.add(e.id);
    return {id:e.id,status:'applied'};
  });
  return {balances,versions,receipts};
}
module.exports={solve};

