// A min-heap selects the smallest ID among the nodes currently ready.
function push(heap, node) {
  let i = heap.length;
  heap.push(node);
  while (i > 0) {
    const parent = (i - 1) >> 1;
    if (heap[parent].id < node.id) break;
    heap[i] = heap[parent];
    i = parent;
  }
  heap[i] = node;
}

function pop(heap) {
  const first = heap[0];
  const last = heap.pop();
  if (heap.length) {
    let i = 0;
    while (i * 2 + 1 < heap.length) {
      let child = i * 2 + 1;
      if (child + 1 < heap.length && heap[child + 1].id < heap[child].id) child++;
      if (last.id < heap[child].id) break;
      heap[i] = heap[child];
      i = child;
    }
    heap[i] = last;
  }
  return first;
}

function solve(input) {
  const nodes = new Map(input.nodes.map(node => [node.id, {
    id: node.id,
    revision: node.revision,
    deps: [],
    consumers: [],
    generation: 0,
    builtRevision: undefined,
    dependencyBuilds: [],
    remaining: 0
  }]));
  // Dependencies cannot change in this contract. Normalize them once.
  for (const source of input.nodes) {
    const node = nodes.get(source.id);
    node.deps = [...new Set(source.deps)].map(id => nodes.get(id));
    for (const dependency of node.deps) dependency.consumers.push(node);
  }

  return input.requests.map(request => {
    for (const change of request.changes) nodes.get(change.id).revision = change.revision;
    const needed = new Set();
    const stack = [];
    for (const id of request.targets) {
      const node = nodes.get(id);
      if (!needed.has(node)) {
        needed.add(node);
        stack.push(node);
      }
    }
    while (stack.length) {
      const node = stack.pop();
      for (const dependency of node.deps) {
        if (!needed.has(dependency)) {
          needed.add(dependency);
          stack.push(dependency);
        }
      }
    }

    const ready = [];
    for (const node of needed) {
      node.remaining = node.deps.length;
      if (!node.remaining) push(ready, node);
    }
    const built = [];
    const cached = [];
    while (ready.length) {
      const node = pop(ready);
      const valid = node.generation !== 0 && node.builtRevision === node.revision &&
        node.deps.every((dependency, i) => dependency.generation === node.dependencyBuilds[i]);
      if (valid) {
        cached.push(node.id);
      } else {
        node.generation++;
        node.builtRevision = node.revision;
        node.dependencyBuilds = node.deps.map(dependency => dependency.generation);
        built.push(node.id);
      }
      for (const consumer of node.consumers) {
        if (needed.has(consumer) && --consumer.remaining === 0) push(ready, consumer);
      }
    }
    return { built, cached };
  });
}

module.exports = { solve };

