// A min-heap selects the smallest ID among the nodes currently ready.
function push(heap, node) {
  let i = heap.length;
  heap.push(node);
  while (i > 0) {
    const parent = (i - 1) >> 1;
    if (heap[parent].id < node.id) break;
    heap[i] = heap[parent];
    i = parent;
  }
  heap[i] = node;
}

function pop(heap) {
  const first = heap[0];
  const last = heap.pop();
  if (heap.length) {
    let i = 0;
    while (i * 2 + 1 < heap.length) {
      let child = i * 2 + 1;
      if (child + 1 < heap.length && heap[child + 1].id < heap[child].id) child++;
      if (last.id < heap[child].id) break;
      heap[i] = heap[child];
      i = child;
    }
    heap[i] = last;
  }
  return first;
}

function solve(input) {
  const nodes = new Map(input.nodes.map(node => [node.id, {
    id: node.id,
    revision: node.revision,
    deps: [],
    consumers: new Set(),
    generation: 0,
    builtRevision: undefined,
    builtDeps: [],
    dependencyBuilds: [],
    remaining: 0
  }]));
  // Canonical dependency order makes set identity independent of input order.
  function setDependencies(node, ids) {
    for (const dependency of node.deps) dependency.consumers.delete(node);
    node.deps = [...new Set(ids)].sort().map(id => nodes.get(id));
    for (const dependency of node.deps) dependency.consumers.add(node);
  }
  for (const source of input.nodes) {
    setDependencies(nodes.get(source.id), source.deps);
  }

  return input.requests.map(request => {
    for (const change of request.changes) {
      const node = nodes.get(change.id);
      if (change.revision !== undefined) node.revision = change.revision;
      if (change.deps !== undefined) setDependencies(node, change.deps);
    }
    const needed = new Set();
    const stack = [];
    for (const id of request.targets) {
      const node = nodes.get(id);
      if (!needed.has(node)) {
        needed.add(node);
        stack.push(node);
      }
    }
    while (stack.length) {
      const node = stack.pop();
      for (const dependency of node.deps) {
        if (!needed.has(dependency)) {
          needed.add(dependency);
          stack.push(dependency);
        }
      }
    }

    const ready = [];
    for (const node of needed) {
      node.remaining = node.deps.length;
      if (!node.remaining) push(ready, node);
    }
    // Check the entire required graph before changing any successful build.
    const order = [];
    while (ready.length) {
      const node = pop(ready);
      order.push(node);
      for (const consumer of node.consumers) {
        if (needed.has(consumer) && --consumer.remaining === 0) push(ready, consumer);
      }
    }
    if (order.length !== needed.size) return { error: 'cycle', built: [], cached: [] };

    const built = [];
    const cached = [];
