      const valid = node.generation !== 0 && node.builtRevision === node.revision &&
        node.deps.length === node.builtDeps.length &&
        node.deps.every((dependency, i) => dependency === node.builtDeps[i] &&
          dependency.generation === node.dependencyBuilds[i]);
