function solve(input) {
  const roles = new Map(input.roles.map(role => [role.id, role]));
  const users = new Map(input.users.map(user => [user.id, new Set(user.roles)]));
  return input.queries.map(query => {
    const assigned = users.get(query.user);
    if (!assigned) return 'deny';
    let allowed = false;
    for (const id of assigned) {
      for (const rule of roles.get(id).rules) {
        if (rule.tenant === query.tenant &&
            (rule.resource === '*' || rule.resource === query.resource) &&
            (rule.action === '*' || rule.action === query.action)) {
          // Denies take priority over allows in all assigned roles.
          if (rule.effect === 'deny') return 'deny';
          allowed = true;
        }
      }
    }
    return allowed ? 'allow' : 'deny';
  });
}
module.exports = { solve };

