// Visit each reachable role once. An active parent identifies a cycle.
function collectRules(assigned, roles) {
  const state = new Map();
  const rules = [];
  for (const id of assigned) {
    if (state.has(id)) continue;
    state.set(id, 1);
    const stack = [{ role: roles.get(id), next: 0 }];
    while (stack.length) {
      const frame = stack[stack.length - 1];
      if (frame.next < frame.role.parents.length) {
        const parent = frame.role.parents[frame.next++];
        if (state.get(parent) === 1) return null;
        if (state.get(parent) === 2) continue;
        state.set(parent, 1);
        stack.push({ role: roles.get(parent), next: 0 });
      } else {
        for (const rule of frame.role.rules) rules.push(rule);
        state.set(frame.role.id, 2);
        stack.pop();
      }
    }
  }
  return rules;
}

function solve(input) {
  const roles = new Map(input.roles.map(role => [role.id, role]));
  const users = new Map(input.users.map(user => [user.id, user.roles]));
  const queriesByUser = new Map();
  const results = input.queries.map(() => 'deny');
  input.queries.forEach((query, index) => {
    if (!queriesByUser.has(query.user)) queriesByUser.set(query.user, []);
    queriesByUser.get(query.user).push(index);
  });

  // Process one user at a time so rule collections do not accumulate in memory.
  for (const [user, indices] of queriesByUser) {
    const assigned = users.get(user);
    if (!assigned) continue;
    const rules = collectRules(assigned, roles);
    if (rules === null) continue;
    for (const index of indices) {
      const query = input.queries[index];
      for (const rule of rules) {
        if (rule.tenant === query.tenant &&
            (rule.resource === '*' || rule.resource === query.resource) &&
            (rule.action === '*' || rule.action === query.action) &&
            (rule.until === undefined || query.time < rule.until)) {
          if (rule.effect === 'deny') {
            results[index] = 'deny';
            break;
          }
          results[index] = 'allow';
        }
      }
    }
  }
  return results;
}
module.exports = { solve };
